from odoo import api, fields, models
from odoo.exceptions import AccessError, UserError
from odoo.fields import Command

# Every type but 'other' is generated by the system. Channel modules add their charges
# (e.g. delivery) with selection_add.
LINE_TYPES = [
    ('service', "Service"),
    ('addon', "Add-on"),
    ('urgent', "Urgent Surcharge"),
    ('storage', "Storage Fee"),
    ('advance', "Advance"),
    ('other', "Other"),
]
PRICE_FIELDS = {'price_unit', 'discount', 'product_id', 'tax_ids'}


class LaundryOrderLine(models.Model):
    _name = 'ki.laundry.order.line'
    _description = "Laundry Billing Line"
    _order = 'order_id, sequence, id'
    _check_company_auto = True

    order_id = fields.Many2one('ki.laundry.order', required=True, ondelete='cascade', index=True)
    intake_id = fields.Many2one('ki.laundry.order.intake', ondelete='cascade', index='btree_not_null')
    sequence = fields.Integer(default=10)
    line_type = fields.Selection(LINE_TYPES, default='other', required=True)
    company_id = fields.Many2one(related='order_id.company_id', store=True, index=True)
    currency_id = fields.Many2one(related='order_id.currency_id', store=True)
    partner_id = fields.Many2one(related='order_id.partner_id', store=True, index=True)
    state = fields.Selection(related='order_id.state', store=True)
    product_id = fields.Many2one('product.product', string="Product", required=True, check_company=True,
                                 index=True, ondelete='restrict')
    product_tmpl_id = fields.Many2one(related='product_id.product_tmpl_id', string="Service", store=True,
                                      index='btree_not_null')
    garment_id = fields.Many2one(related='product_id.ki_laundry_garment_id', store=True, index='btree_not_null')
    name = fields.Text(string="Description", compute='_compute_name', store=True, readonly=False, precompute=True)
    product_uom_id = fields.Many2one('uom.uom', string="Unit", compute='_compute_product_uom_id',
                                     store=True, readonly=False, precompute=True)
    product_uom_qty = fields.Float(string="Quantity", digits='Product Unit', default=1.0)
    price_unit = fields.Float(string="Unit Price", digits='Product Price')
    discount = fields.Float(string="Discount (%)", digits='Discount')
    price_is_manual = fields.Boolean(
        string="Manual Price", help="The price is kept when quantities change.")
    tax_ids = fields.Many2many(
        'account.tax', 'ki_laundry_line_tax_rel', 'line_id', 'tax_id', string="Taxes", check_company=True,
        compute='_compute_tax_ids', store=True, readonly=False,
        domain="[('type_tax_use', '=', 'sale')]")
    price_subtotal = fields.Monetary(compute='_compute_amount', store=True, string="Subtotal")
    price_tax = fields.Monetary(compute='_compute_amount', store=True, string="Tax")
    price_total = fields.Monetary(compute='_compute_amount', store=True, string="Total")
    item_ids = fields.Many2many('ki.laundry.order.item', 'ki_laundry_item_line_rel', 'line_id', 'item_id',
                                string="Items", copy=False)
    invoice_line_ids = fields.Many2many(
        'account.move.line', 'ki_laundry_line_invoice_rel', 'laundry_line_id', 'invoice_line_id',
        string="Invoice Lines", copy=False, readonly=True)
    qty_invoiced = fields.Float(compute='_compute_qty_invoiced', store=True, digits='Product Unit')
    qty_to_invoice = fields.Float(compute='_compute_qty_to_invoice', store=True, digits='Product Unit')

    # ------------------------------------------------------------------
    # Computes
    # ------------------------------------------------------------------

    @api.depends('product_id')
    def _compute_name(self):
        for line in self:
            if not line.product_id:
                continue
            if line.name and line.line_type not in ('service', 'addon'):
                continue
            line.name = line.product_id.display_name

    @api.depends('product_id')
    def _compute_product_uom_id(self):
        for line in self:
            if not line.product_uom_id or line.product_id.uom_id != line.product_uom_id:
                line.product_uom_id = line.product_id.uom_id

    @api.depends('product_id', 'company_id')
    def _compute_tax_ids(self):
        for line in self:
            company = line.company_id or line.order_id.company_id or self.env.company
            taxes = line.product_id.taxes_id._filter_taxes_by_company(company)
            fiscal_position = line.order_id.fiscal_position_id
            line.tax_ids = fiscal_position.map_tax(taxes) if fiscal_position else taxes

    def _ki_prepare_base_line(self):
        self.ensure_one()
        order = self.order_id
        return self.env['account.tax']._prepare_base_line_for_taxes_computation(
            self,
            quantity=self.product_uom_qty,
            partner_id=order.partner_id,
            currency_id=order.currency_id or order.company_id.currency_id,
        )

    @api.depends('product_uom_qty', 'discount', 'price_unit', 'tax_ids', 'currency_id')
    def _compute_amount(self):
        AccountTax = self.env['account.tax']
        for line in self:
            company = line.company_id or self.env.company
            base_line = line._ki_prepare_base_line()
            AccountTax._add_tax_details_in_base_line(base_line, company)
            AccountTax._round_base_lines_tax_details([base_line], company)
            line.price_subtotal = base_line['tax_details']['total_excluded_currency']
            line.price_total = base_line['tax_details']['total_included_currency']
            line.price_tax = line.price_total - line.price_subtotal

    @api.depends('invoice_line_ids.move_id.state', 'invoice_line_ids.quantity', 'invoice_line_ids.product_uom_id')
    def _compute_qty_invoiced(self):
        for line in self:
            qty = 0.0
            for invoice_line in line.invoice_line_ids:
                move = invoice_line.move_id
                if move.state == 'cancel' or move.move_type not in ('out_invoice', 'out_refund'):
                    continue
                quantity = invoice_line.quantity
                if invoice_line.product_uom_id and line.product_uom_id \
                        and invoice_line.product_uom_id != line.product_uom_id:
                    quantity = invoice_line.product_uom_id._compute_quantity(quantity, line.product_uom_id)
                qty += quantity if move.move_type == 'out_invoice' else -quantity
            line.qty_invoiced = qty

    @api.depends('qty_invoiced', 'product_uom_qty', 'line_type', 'order_id.state', 'order_id.financial_path',
                 'order_id.is_stopped', 'intake_id.weight_actual', 'intake_id.pricing_mode')
    def _compute_qty_to_invoice(self):
        for line in self:
            order = line.order_id
            if line.line_type == 'advance' or order._ki_paid_elsewhere() or order.state == 'draft' \
                    or (order.state == 'cancelled' and not order.is_stopped):
                line.qty_to_invoice = 0.0
            elif line.intake_id.pricing_mode == 'kg' and not line.intake_id.weight_actual:
                # Weight is only an estimate until the load is weighed.
                line.qty_to_invoice = 0.0
            else:
                line.qty_to_invoice = line.product_uom_qty - line.qty_invoiced

    # ------------------------------------------------------------------
    # Pricing
    # ------------------------------------------------------------------

    def _ki_get_price_and_discount(self):
        self.ensure_one()
        order = self.order_id
        company = order.company_id
        product = self.product_id.with_company(company)
        quantity = self.product_uom_qty or 1.0
        uom = self.product_uom_id or product.uom_id
        date = order.price_date or fields.Datetime.now()
        currency = order.currency_id or company.currency_id
        discount = 0.0
        pricelist = order.pricelist_id
        if pricelist:
            price, rule_id = pricelist._get_product_price_rule(
                product, quantity, currency=currency, uom=uom, date=date)
            rule = self.env['product.pricelist.item'].browse(rule_id)
            if rule and rule.compute_price == 'percentage':
                base_price = rule._compute_price_before_discount(
                    product=product, quantity=quantity, uom=uom, date=date, currency=currency)
                if base_price > 0 and currency.compare_amounts(base_price, price) > 0:
                    discount = (base_price - price) / base_price * 100.0
                    price = base_price
        else:
            price = product.uom_id._compute_price(product.lst_price, uom)
            if product.currency_id and product.currency_id != currency:
                price = product.currency_id._convert(price, currency, company, date)
        taxes = product.taxes_id._filter_taxes_by_company(company)
        price = product._get_tax_included_unit_price_from_price(
            price, product_taxes=taxes, fiscal_position=order.fiscal_position_id)
        return price, discount

    def _ki_recompute_price(self):
        for line in self:
            if line.price_is_manual or line.qty_invoiced or line.line_type not in ('service', 'addon', 'other'):
                continue
            price, discount = line._ki_get_price_and_discount()
            line.with_context(ki_laundry_system=True).write({'price_unit': price, 'discount': discount})

    def _ki_recompute_taxes(self):
        lines = self.filtered(lambda l: not l.qty_invoiced)
        lines._compute_tax_ids()

    # ------------------------------------------------------------------
    # ORM guards
    # ------------------------------------------------------------------

    @api.onchange('price_unit', 'discount')
    def _onchange_price_manual(self):
        if self.line_type in ('service', 'addon', 'other'):
            self.price_is_manual = True

    @api.onchange('product_id')
    def _onchange_product_id_price(self):
        if self.product_id and self.line_type == 'other' and self.order_id:
            self.price_is_manual = False
            self.price_unit, self.discount = self._ki_get_price_and_discount()

    @api.model_create_multi
    def create(self, vals_list):
        if not self.env.context.get('ki_laundry_system'):
            for vals in vals_list:
                if vals.get('line_type', 'other') != 'other':
                    raise UserError(self.env._(
                        "Service lines are generated from the intake lines. Add garments or loads instead."))
        lines = super().create(vals_list)
        if not self.env.context.get('ki_laundry_system'):
            for line in lines:
                if not line.order_id.prices_editable:
                    raise UserError(self.env._("Lines cannot be added once processing has started."))
            lines.filtered(lambda l: not l.price_is_manual and not l.price_unit)._ki_recompute_price()
        return lines

    def write(self, vals):
        if not self.env.context.get('ki_laundry_system'):
            if PRICE_FIELDS & set(vals):
                for line in self:
                    if line.line_type != 'other' and 'product_id' in vals:
                        raise UserError(self.env._("The product of generated lines cannot be changed."))
                    if not line.order_id.prices_editable:
                        raise UserError(self.env._("Prices are final once processing has started."))
                    if line.order_id.state != 'draft' and not line.order_id._ki_is_manager():
                        raise AccessError(self.env._("Only laundry managers can change prices of received orders."))
            if {'product_uom_qty', 'line_type', 'intake_id'} & set(vals) \
                    and self.filtered(lambda l: l.line_type != 'other'):
                raise UserError(self.env._(
                    "Quantities of generated lines follow the intake lines. Change the intake line instead."))
        if self.filtered('qty_invoiced') and (PRICE_FIELDS | {'product_uom_qty'}) & set(vals) \
                and not self.env.context.get('ki_laundry_invoiced_ok'):
            for line in self.filtered('qty_invoiced'):
                new_qty = vals.get('product_uom_qty', line.product_uom_qty)
                if PRICE_FIELDS & set(vals) or new_qty < line.qty_invoiced:
                    raise UserError(self.env._(
                        "Line '%s' is already invoiced. Issue a credit note before changing it.", line.name))
        return super().write(vals)

    def unlink(self):
        if not self.env.context.get('ki_laundry_system'):
            for line in self:
                if line.line_type != 'other':
                    raise UserError(self.env._(
                        "Generated lines cannot be deleted. Change the intake lines or order options instead."))
                if not line.order_id.prices_editable:
                    raise UserError(self.env._("Lines cannot be removed once processing has started."))
        if self.filtered('qty_invoiced'):
            raise UserError(self.env._("Invoiced lines cannot be deleted. Issue a credit note first."))
        return super().unlink()

    # ------------------------------------------------------------------
    # Invoicing
    # ------------------------------------------------------------------

    def _ki_prepare_invoice_line(self, quantity):
        self.ensure_one()
        return {
            'display_type': 'product',
            'product_id': self.product_id.id,
            'name': self.name or self.product_id.display_name,
            'quantity': quantity,
            'product_uom_id': self.product_uom_id.id,
            'price_unit': self.price_unit,
            'discount': self.discount,
            'tax_ids': [Command.set(self.tax_ids.ids)],
            'ki_laundry_line_ids': [Command.link(self.id)],
        }
